SELECT CASE WHEN duration_sec >= 439 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, DATE_TRUNC('WEEK', event_time) AS week_start, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, SIZE(COLLECT_SET(page)) AS num_pages, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count, COUNT_IF(page = '/search') AS search_events, COUNT(*) AS cnt, GROUPING(CASE WHEN duration_sec >= 439 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM web_events GROUP BY ROLLUP (CASE WHEN duration_sec >= 439 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', event_time)) HAVING checkout_count >= 1
